                $('input[name=bnd_isu_methd_cd][value="' + jsonData.bnd_isu_methd_cd + '"]').attr("checked", true);
                $c.util.getComponent('cal_isuDd').setValue($c.date.dateFormat(jsonData.isu_dd));
                $c.util.getComponent('cal_expDd').setValue($c.date.dateFormat(jsonData.exp_dd));
                $('#slc_currTpCd').find('option[value="' + jsonData.curr_tp_cd + '"]').attr("selected", true);
                scwin.fnOnchangeCurr();
                if (jsonData.curr_tp_cd === "1") {
                    $c.util.getComponent('ipt_isuAmtK').setValue(jsonData.isu_amt);
                    if (jsonData.isu_amt != null) {
                        $c.util.getComponent('txt_isuAmtMoney').setValue($c.num.formatNumberKor(String(((($('#ipt_isuAmtK')[0]) && ($('#ipt_isuAmtK')[0]).getValue) ? ($('#ipt_isuAmtK')[0]).getValue() : (((($('#ipt_isuAmtK')[0]) && typeof ($('#ipt_isuAmtK')[0]).val === 'function') ? ($('#ipt_isuAmtK')[0]).val() : ((($('#ipt_isuAmtK')[0]) && ($('#ipt_isuAmtK')[0]).value !== undefined) ? ($('#ipt_isuAmtK')[0]).value : ($('#ipt_isuAmtK')[0]))))) == null ? '' : ((($('#ipt_isuAmtK')[0]) && ($('#ipt_isuAmtK')[0]).getValue) ? ($('#ipt_isuAmtK')[0]).getValue() : (((($('#ipt_isuAmtK')[0]) && typeof ($('#ipt_isuAmtK')[0]).val === 'function') ? ($('#ipt_isuAmtK')[0]).val() : ((($('#ipt_isuAmtK')[0]) && ($('#ipt_isuAmtK')[0]).value !== undefined) ? ($('#ipt_isuAmtK')[0]).value : ($('#ipt_isuAmtK')[0])))))).replace(/,/g, '')));
                        $c.util.getComponent('ipt_isuAmtK').setValue($c.num.formatNumber($c.util.getComponent('ipt_isuAmtK').getValue()));
                    }
                } else {
                    $c.util.getComponent('ipt_isuAmtD').setValue(jsonData.isu_amt);
                }
                $('input[name=rd_domFornIsuTpCd][value="' + jsonData.dom_forn_isu_tp_cd + '"]').attr("checked", true);
                $('input[name=rd_fncUlyTpCd][value="' + jsonData.fnc_uly_tp_cd + '"]').attr("checked", true);
                $c.util.getComponent('ipt_ulyDtlContn').setValue(jsonData.uly_dtl_contn);
                $('#princ_grt_yn_' + jsonData.princ_grt_yn).attr("checked", true);
                $c.util.getComponent('ipt_upPartcRto').setValue(jsonData.up_partc_rto);
                $c.util.getComponent('ipt_maxYd').setValue(jsonData.max_yd);
                $c.util.getComponent('ipt_maxLossRt').setValue(jsonData.max_loss_rt);
                $c.util.getComponent('ipt_elsDlsCondContn1').setValue(jsonData.els_dls_cond_contn1);
                $c.util.getComponent('ipt_elsDlsCondContn2').setValue(jsonData.els_dls_cond_contn2);
                $('input[name=rght_tp_cd][value="' + jsonData.rght_tp_cd + '"]').attr("checked", true);
                $c.util.getComponent('ipt_nusualIsuCondContn').setValue(jsonData.nusual_isu_cond_contn);
                scwin.changeGrt(jsonData.princ_grt_yn);
                $c.util.getComponent('ipt_princGrtRt').setValue(jsonData.princ_grt_rt);
                $c.util.getComponent('ipt_stdIsuCd').setValue('');
                const cfi_group = jsonData.cfi_cd.substring(1, 2);
                const cfi_set1 = jsonData.cfi_cd.substring(2, 3);
                const cfi_set2 = jsonData.cfi_cd.substring(3, 4);
                const cfi_set3 = jsonData.cfi_cd.substring(4, 5);
                const cfi_set4 = jsonData.cfi_cd.substring(5, 6);
                $c.util.getComponent("dma_inIsuNmReq").set("group", cfi_group);
                $('input[name=group][value="' + cfi_group + '"]').attr("checked", true);
                scwin.chg_group($("#group_" + cfi_group));
                $c.util.getComponent('slc_attr01').setValue(cfi_set1);
                $c.util.getComponent('slc_attr02').setValue(cfi_set2);
                $c.util.getComponent('slc_attr03').setValue(cfi_set3);
                $c.util.getComponent('slc_attr04').setValue(cfi_set4);
                $c.util.getComponent('ipt_cfiCd').setValue(jsonData.cfi_cd);
                scwin.chg_attr();
                $c.util.getComponent('ipt_fisnVal').setValue(jsonData.fisn_val);
