                    }
                }
                if (applId === "" || applId === "undefined") {
                    await $c.win.alert("직전 입력내용이 반영되었습니다.\n\r수정후 신청하시기 바랍니다.");
                } else {
                    await $c.win.alert("기신청한 내용이 반영되었습니다.\n\r수정후 재신청하시기 바랍니다.");
                }
                if ('' + dma_companyInfoVO.get("isurSecuElsDlsYn") + '' === 'N') {
                    $("#els_dls_tp_cd_1").attr("disabled", true);
                    (($c.util.getComponent('rd_elsDlsTpCd2')) && ($c.util.getComponent('rd_elsDlsTpCd2')).setDisabled ? ($c.util.getComponent('rd_elsDlsTpCd2')).setDisabled((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
