 * @hidden N
 */
scwin.fnOnchangeCurr = function () {
    if ($c.util.getComponent('slc_currTpCd').getValue() === "1") {
        $c.util.getComponent("ipt_isuAmtK").setStyle("text-align", "right"); $c.util.getComponent("ipt_isuAmtK").setStyle("display", "");
        $c.util.getComponent("txt_isuAmtMoney").setStyle("display", "");
        $c.util.getComponent('txt_isuAmtMoney').setLabel("");
        $c.util.getComponent("ipt_isuAmtD").setStyle("display", "none");
        $c.util.getComponent('ipt_isuAmtD').setValue('');
    } else {
        $c.util.getComponent("ipt_isuAmtK").setStyle("display", "none");
        $c.util.getComponent("txt_isuAmtMoney").setStyle("display", "none");
        $c.util.getComponent("ipt_isuAmtD").setStyle("text-align", "right"); $c.util.getComponent("ipt_isuAmtD").setStyle("display", "");
        $c.util.getComponent('ipt_isuAmtK').setValue('');
    }
};

/**
 * @method
 * @name setCfiAttr4
 * @description set Cfi Attr4 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCfiAttr4 = function () {
    const sTmp = $('input[name=rd_fncUlyTpCd]:checked').val();
    if (sTmp === "1") {
        $c.util.getComponent('slc_attr04').setValue("S");
    } else {
        if (sTmp === "2") {
            $c.util.getComponent('slc_attr04').setValue("B");
        } else {
            if (sTmp === "3") {
                $c.util.getComponent('slc_attr04').setValue("I");
            } else {
                if (sTmp === "4") {
                    $c.util.getComponent('slc_attr04').setValue("T");
                } else {
                    if (sTmp === "5") {
                        $c.util.getComponent('slc_attr04').setValue("D");
                    } else {
                        if (sTmp === "6") {
                            $c.util.getComponent('slc_attr04').setValue("C");
                        } else {
                            if (sTmp === "9") {
                                $c.util.getComponent('slc_attr04').setValue("M");
                            }
                        }
                    }
                }
            }
        }
    }
    scwin.chg_attr();
};

